package dev.sablelife.testing;
import dev.sablelife.SableLife;import dev.sablelife.heart.*;import dev.sablelife.module.*;import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;import dev.ryanhcode.sable.companion.math.BoundingBox3i;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.entity.EntityType;import net.minecraft.world.phys.Vec3;import net.neoforged.neoforge.gametest.*;import java.util.*;
@GameTestHolder("sablelife_particle_tests") @PrefixGameTestTemplate(false)
public final class PulseVisualGameTests {
 @GameTest(template="combat",batch="pulse_visual_geometry") public static void ShellMovesFromCenterToRadiusAndPersistsItsDuration(GameTestHelper h){var m=new VirtualModule("pulse");var point=new Vec3(12,-30,44);h.assertTrue(m.value("pulseVisual")==0&&PulseVisual.particles(m,point).isEmpty(),"Old style default changed");m.edit("pulseVisual",1,"");for(double r:new double[]{1,5,16})for(int time:new int[]{1,10,200}){m.edit("radius",r,"");m.edit("pulseExpandTime",time,"");var particles=PulseVisual.particles(m,point);h.assertTrue(particles.size()==64,"Shell size exceeded budget");for(var packet:particles)h.assertTrue(packet.from().equals(point)&&Math.abs(packet.to().distanceTo(point)-r)<1e-6&&packet.ticks()==time&&packet.life()>time&&ModuleParticles.valid(packet.id()),"Outward particle path or lifetime wrong");h.assertTrue(particles.stream().anyMatch(p->p.to().y>point.y)&&particles.stream().anyMatch(p->p.to().y<point.y),"Shell lost vertical extent");}var saved=VirtualModule.load(m.save());h.assertTrue(saved.value("pulseVisual")==1&&saved.value("pulseExpandTime")==200&&ModulePreset.create(m.save()).value("pulseVisual")==1,"Style failed save/preset round trip");var old=m.save();old.getCompound("Settings").remove("pulseVisual");old.getCompound("Settings").remove("pulseExpandTime");h.assertTrue(VirtualModule.load(old).value("pulseVisual")==0&&VirtualModule.load(old).value("pulseExpandTime")==10,"Old pulse did not retain fixed default");h.succeed();}
 @GameTest(template="combat",batch="pulse_visual_damage") public static void LongVisualStillDamagesImmediatelyAndRespectsCadenceAndWalls(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());var m=c.modules().add("pulse");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos().east(),Direction.EAST)));m.edit("pulseVisual",1,"");m.edit("pulseExpandTime",200,"");m.edit("damage",4,"");m.edit("knockback",0,"");c.tryActivate(TestActors.creative(l));var center=ModuleCombat.origin(c,m,false);var target=EntityType.COW.create(l);target.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(20);target.setHealth(20);target.setPos(center.add(3,-.7,0));target.setNoAi(true);target.setNoGravity(true);l.addFreshEntity(target);var wall=BlockPos.containing(center.add(1.5,0,0));for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)l.setBlockAndUpdate(wall.offset(0,y,z),Blocks.STONE.defaultBlockState());c.modules().tick(c);h.assertTrue(target.getHealth()==20,"Pulse crossed fixture wall: center="+center+", now="+ModuleCombat.origin(c,m,false)+", target="+target.getBoundingBox()+", wall="+wall);for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)l.setBlockAndUpdate(wall.offset(0,y,z),Blocks.AIR.defaultBlockState());c.modules().clearRuntime();c.modules().tick(c);h.assertTrue(target.getHealth()==16,"Damage waited for visual expansion");c.modules().tick(c);h.assertTrue(target.getHealth()==16,"Visual created additional hits");m.edit("enabled",0,"");c.modules().clearRuntime();c.modules().tick(c);h.assertTrue(target.getHealth()==16,"Disabled pulse still hit");target.discard();h.succeed();}
 @GameTest(template="combat",batch="pulse_custom_particles") public static void IndependentCenterAndWaveSelectionPersistsAndEmptyDisablesVisuals(GameTestHelper h){var m=new VirtualModule("pulse");m.edit("pulseVisual",1,"");var wave=m.movementParticles("Wave");var center=m.movementParticles("Center");h.assertTrue(center.particles().equals(List.of("minecraft:sonic_boom"))&&wave.particles().equals(List.of("minecraft:electric_spark")),"Default visual selections changed");wave.editParticle("remove","minecraft:electric_spark");wave.editParticle("add","minecraft:flame");wave.editParticle("size","minecraft:flame",2);wave.editParticle("duration","minecraft:flame",2);center.editParticle("remove","minecraft:sonic_boom");center.editParticle("add","minecraft:poof");var packets=PulseVisual.particles(m,Vec3.ZERO);h.assertTrue(packets.size()==64&&packets.stream().allMatch(p->p.id().equals("minecraft:flame")&&p.size()==2&&p.life()==40),"Chosen wave type/size/lifetime not applied");var loaded=VirtualModule.load(m.save());h.assertTrue(loaded.movementParticles("Center").particles().equals(List.of("minecraft:poof"))&&PulseVisual.particles(loaded,Vec3.ZERO).getFirst().size()==2&&ModulePreset.create(m.save()).movementParticles("Wave").particles().equals(List.of("minecraft:flame")),"Selections failed save or preset");wave.editParticle("remove","minecraft:flame");center.editParticle("remove","minecraft:poof");loaded=VirtualModule.load(m.save());h.assertTrue(PulseVisual.particles(loaded,Vec3.ZERO).isEmpty()&&loaded.movementParticles("Center").particles().isEmpty(),"Empty selections restored hardcoded particles");h.succeed();}

 @GameTest(template="combat",batch="pulse_particle_editor") public static void ParticleSelectorsEditParentAndLockWhenActive(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(pos,SableLife.HEART.get().defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,pos,List.of(pos),new BoundingBox3i(pos.getX(),pos.getY(),pos.getZ(),pos.getX(),pos.getY(),pos.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());var m=c.modules().add("pulse");var p=new MenuPlayer(l);p.setPos(ModuleArena.corePosition(c));var dashboard=new HeartDashboardMenu(1,p.getInventory(),c);h.assertTrue(dashboard.action(p,c.modules().revision(),m.id(),"effects","pulseWaveParticles",0,""),"Pulse selector did not open");h.assertTrue(p.containerMenu instanceof EffectSelectionMenu,"Wrong particle editor");var menu=(EffectSelectionMenu)p.containerMenu;var wave=m.movementParticles("Wave");h.assertTrue(menu.action(p,wave.id(),"add",0,"minecraft:flame")&&wave.particles().contains("minecraft:flame"),"Editor did not change parent wave selection");c.tryActivate(p);h.assertTrue(!menu.action(p,wave.id(),"remove",0,"minecraft:flame"),"Active editor changed visual settings");h.succeed();}

 private static final class MenuPlayer extends net.neoforged.neoforge.common.util.FakePlayer {private int next;MenuPlayer(net.minecraft.server.level.ServerLevel level){super(level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"PulseAuthor"));setGameMode(net.minecraft.world.level.GameType.CREATIVE);}@Override public java.util.OptionalInt openMenu(net.minecraft.world.MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> extra){closeContainer();containerMenu=provider.createMenu(++next,getInventory(),this);return java.util.OptionalInt.of(next);}}

}
